import * as React from "react";
import "./Loader.scss";

export interface LoaderProps {
  id: string;
  progress?: number;
  colour?: string;
  bar_width?: string;
  showProgress: boolean;
}

const LinearLoader: React.FC<LoaderProps> = ({
  id,
  progress = 100,
  colour = "#0065BD",
  bar_width = "100%",
  showProgress = true,
}) => {

  return (
    <div id={id} style={{ width: bar_width }}>
      {showProgress && (
        <div className="loader-font loader-font-display">
          {progress}%
        </div>
      )}

      <div className="loader-container">
        <div
          className="linear-loader"
          style={{
            width: `${progress}%`,
            backgroundColor: colour,
            transition: "width 0.3s ease"
          }}
        />
      </div>
    </div>
  );
};

export default LinearLoader;
